import sys
from collections import deque

def main():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    n, k = map(int, lines[0].split())
    c = [[0]*n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        for j in range(n):
            c[i][j] = row[j]

    def max_flow_with_k(c, k):
        n = len(c)
        flow = 0
        parent = [-1] * n
        while True:
            q = deque()
            q.append(0)
            parent = [-1] * n
            parent[0] = -2
            found = False
            while q and not found:
                u = q.popleft()
                for v in range(n):
                    if parent[v] == -1 and c[u][v] > 0:
                        parent[v] = u
                        if v == n-1:
                            found = True
                            break
                        q.append(v)
            if not found:
                break
            path_flow = float('inf')
            v = n-1
            while v != 0:
                u = parent[v]
                path_flow = min(path_flow, c[u][v])
                v = u
            v = n-1
            while v != 0:
                u = parent[v]
                c[u][v] -= path_flow
                c[v][u] += path_flow
                v = u
            flow += path_flow
        return flow

    def binary_search(c, k):
        low = 0
        high = k
        best = 0
        while low <= high:
            mid = (low + high) // 2
            temp_c = [row[:] for row in c]
            total_increase = 0
            for i in range(n):
                for j in range(n):
                    if temp_c[i][j] > 0:
                        delta = min(mid, k - total_increase)
                        temp_c[i][j] += delta
                        total_increase += delta
                        if total_increase >= k:
                            break
                if total_increase >= k:
                    break
            if total_increase > k:
                high = mid - 1
                continue
            current_flow = max_flow_with_k(temp_c, k - total_increase)
            if current_flow > best:
                best = current_flow
                low = mid + 1
            else:
                high = mid - 1
        return best

